layout.customStyles:
/* The frame of CherryMountain Brewery: header, menu, and sign-in dialog. Colors are the brand tokens. */
.header {
  background-image: linear-gradient(#E2552B, #E2552B);
  background-size: 100% 3px;
  background-repeat: no-repeat;
  background-position: left bottom;
}
.header .header-items-button button { pointer-events: none; }
.header .header-items-button .mdc-button__label { font-weight: 700; }
.header .header-login mat-icon[style*="59, 144, 255"] { color: #F4A93B !important; }
.sidenav-menu .sidenav-header { height: 56px !important; padding-bottom: 0 !important; }
.sidenav-menu .sidenav-header img { width: 48px; height: 48px; }
.mat-mdc-dialog-container:has(app-login) {
  --mdc-dialog-container-color: #2A2A30;
  --mdc-dialog-subhead-color: #EFEFEF;
  --mdc-dialog-supporting-text-color: #EFEFEF;
}
.mat-mdc-dialog-container:has(app-login) .mdc-dialog__surface { border-top: 3px solid #E2552B; }
app-login h1.mat-mdc-dialog-title::before {
  content: "";
  display: block;
  width: 48px;
  height: 48px;
  margin: 14px 0 10px;
  background: url(_images/Brand/icon.svg) center / contain no-repeat;
}
app-login .my-form-field span { color: #EFEFEF; }
app-login .my-form-field input { background-color: #1B1B1F; color: #EFEFEF; }
.mat-mdc-dialog-container app-login .mat-mdc-raised-button.mat-primary {
  --mdc-protected-button-container-color: #E2552B;
  --mdc-protected-button-label-text-color: #EFEFEF;
}
.mat-mdc-dialog-container app-login .mat-mdc-raised-button.mat-unthemed {
  --mdc-protected-button-container-color: #55555D;
  --mdc-protected-button-label-text-color: #EFEFEF;
}
